// Share definitions with the full laboratory; keep reference marks independent of sounding keys.
stopSong();accompaniment.hidden=true;
const pocketLab=document.createElement('section');pocketLab.id='pianoChordLab';pocketLab.setAttribute('aria-label','随身和弦查询');
pocketLab.innerHTML=`<div class="pocket-searchbar"><button id="pocketExpand" aria-expanded="true" aria-controls="pocketBrowser">和弦查询 <span>⌃</span></button><label class="pocket-root-label">根音<select id="pocketRoot" aria-label="小钢琴和弦根音">${roots.map((r,i)=>`<option value="${i}">${r[0]}</option>`).join('')}</select></label><label class="pocket-search">⌕ <input id="pocketSearch" type="search" autocomplete="off" spellcheck="false" aria-label="搜索小钢琴和弦" placeholder="搜名称或符号，如 小七、add9、F#m7"></label></div><div id="pocketBrowser"><div id="pocketGroups" class="pocket-groups" role="group" aria-label="和弦分类">${[['all','全部'],['triad','三和弦'],['seventh','七和弦'],['sus','挂留'],['extended','扩展'],['added','加音']].map(([id,name])=>`<button data-pocket-group="${id}" aria-pressed="${id==='all'}">${name}</button>`).join('')}<span id="pocketCount" role="status"></span></div><div id="pocketResults" class="pocket-results" role="group" aria-label="和弦搜索结果"></div></div><div class="pocket-reading"><div id="pocketSummary" aria-live="polite"></div><div class="pocket-actions"><button id="pocketHear" disabled>▶ 齐奏</button><button id="pocketArpeggio" disabled>♪ 逐音</button><button id="pocketClear" disabled>清除标记</button></div></div><details id="pocketDetails" hidden><summary>构成与音程 <span id="pocketFormula"></span></summary><div id="pocketTones"></div><p id="pocketExplanation"></p></details>`;
accompaniment.before(pocketLab);const pocketHome=document.createComment('portable chord lookup home');pocketLab.before(pocketHome);
let pocketChord=null,pocketGroup='all',pocketQueryRoot=null,pocketAuditionTimers=[],pocketAudioGeneration=0;
const pocketNormalize=s=>s.replace(/M(?=\d)/g,'maj').toLowerCase().replace(/♭/g,'b').replace(/♯/g,'#').replace(/[\s·()（）]/g,'');
function pocketAliases(c){return [c.name,c.name.replace('和弦',''),c.suffix,c.id,c.formula,...(c.id==='major'?['大三','major','maj']:c.id==='minor'?['小三','minor','min']:c.id==='9'?['九和弦','九']:c.id==='add9'?['add九','加九']:c.id==='69'?['六九','69']:c.id==='m7b5'?['半减','ø7']:c.id==='dim'?['减三','减']:c.id==='aug'?['增三','增']:[])].map(pocketNormalize)}
function pocketParse(){let query=$('#pocketSearch').value.trim(),root=null;const m=query.match(/^([A-Ga-g])([#b♯♭]?)(.*)$/);if(m){const tail=pocketNormalize(m[3]);if(!tail||chords.some(c=>pocketAliases(c).includes(tail))){const pc=natural[m[1].toUpperCase()]+(['#','♯'].includes(m[2])?1:['b','♭'].includes(m[2])?-1:0);root=roots.findIndex(r=>r[1]===(pc+12)%12);query=m[3]||'major'}}return {query:pocketNormalize(query),root}}
function pocketResults(){const parsed=pocketParse();pocketQueryRoot=parsed.root;const exact=chords.filter(c=>pocketAliases(c).includes(parsed.query));const matches=chords.filter(c=>(pocketGroup==='all'||c.group===pocketGroup)&&(!parsed.query||(exact.length?exact.includes(c):pocketAliases(c).some(a=>a.includes(parsed.query)))));$('#pocketCount').textContent=`${matches.length} / ${chords.length}`;$('#pocketResults').innerHTML=matches.length?matches.map(c=>`<button data-pocket-chord="${c.id}" aria-pressed="${pocketChord===c}"><b>${roots[parsed.root??+$('#pocketRoot').value][0]}${c.suffix}</b><span>${c.name.replace('和弦','')}</span></button>`).join(''):'<p>没有匹配结果，试试“小七”“add9”或清空搜索。</p>';requestAnimationFrame(constrainDock)}
function pocketMidi(){if(!pocketChord)return [];const root=roots[+$('#pocketRoot').value];return pocketChord.intervals.map(n=>(octave+1)*12+root[1]+n)}
function pocketPaint(){const notes=pocketMidi();$$('#liveKeyboard .live-key').forEach(k=>{const m=(octave+1)*12+(+k.dataset.offset),i=notes.indexOf(m);k.classList.toggle('chord-reference',i>=0);k.classList.toggle('chord-reference-root',i===0);k.querySelector('.pocket-key-mark')?.remove();if(i>=0){const marker=document.createElement('i');marker.className='pocket-key-mark';marker.textContent=i===0?'根':pocketChord.formula.split(' · ')[i]?.split('（')[0]||'音';marker.setAttribute('aria-hidden','true');k.append(marker);k.setAttribute('aria-label',`${pianoNoteName(m)} · ${pocketChord.labels[i]} · 和弦参考音`)}else k.setAttribute('aria-label',pianoNoteName(m))});if(pocketChord){const root=roots[+$('#pocketRoot').value],visible=$$('#liveKeyboard .chord-reference').length;$('#pocketSummary').textContent=`${root[0]}${pocketChord.suffix} · ${pocketChord.name}　${pocketChord.intervals.map((n,i)=>spell(root,n,i,pocketChord)).join(' · ')}${visible<notes.length?'　部分音在当前视窗外':''}`}}
function pocketStop(){pocketAudioGeneration++;pocketAuditionTimers.forEach(clearTimeout);pocketAuditionTimers=[];[...held].filter(id=>id.startsWith('pocket-')).forEach(id=>noteOff(id,true));if(typeof pianoRelease!=='undefined')pianoRelease.clear()}
function pocketRefresh(){pianoKeys();pocketPaint();$('#pocketDetails').hidden=!pocketChord;['#pocketHear','#pocketArpeggio','#pocketClear'].forEach(s=>$(s).disabled=!pocketChord);if(pocketChord){const root=roots[+$('#pocketRoot').value];$('#pocketFormula').textContent=pocketChord.formula;$('#pocketTones').innerHTML=pocketChord.intervals.map((n,i)=>`<span><b>${spell(root,n,i,pocketChord)}</b> ${pocketChord.labels[i]}<small>${n} 半音</small></span>`).join('');$('#pocketExplanation').textContent=pocketChord.text}else{$('#pocketSummary').textContent='选一个和弦看键位，也可以直接自由弹奏。';$('#pocketDetails').open=false}pocketResults()}
function pianoReferenceStart(base){return pocketChord&&Math.max(...pocketMidi())>base+30?base-12:base-18}
function pocketFit(){if(!pianoFullscreenOpen||!pocketChord)return;const notes=pocketMidi(),visible=$$('#liveKeyboard .live-key').map(k=>(octave+1)*12+(+k.dataset.offset));if(notes.some(m=>!visible.includes(m))){releaseAll();$('#fullPianoOctaves').value='4';$('#fullPianoBand').value='-12';pianoKeys()}}
$('#pocketSearch').oninput=()=>{pocketGroup='all';$$('[data-pocket-group]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.pocketGroup==='all'));pocketResults()};
$('#pocketSearch').onkeydown=e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();$('#pocketResults [data-pocket-chord]')?.click()}if(e.key==='Escape'){e.stopPropagation();$('#pocketSearch').value='';pocketResults()}};
$('#pocketGroups').onclick=e=>{const b=e.target.closest('[data-pocket-group]');if(!b)return;pocketGroup=b.dataset.pocketGroup;$$('[data-pocket-group]').forEach(x=>x.setAttribute('aria-pressed',x===b));pocketResults()};
$('#pocketResults').onclick=e=>{const b=e.target.closest('[data-pocket-chord]');if(!b)return;pocketStop();pocketChord=chords.find(c=>c.id===b.dataset.pocketChord);if(pocketQueryRoot!==null)$('#pocketRoot').value=pocketQueryRoot;pocketFit();pocketRefresh()};
$('#pocketRoot').onchange=()=>{pocketStop();$('#pocketSearch').value='';pocketFit();pocketRefresh()};
$('#pocketExpand').onclick=()=>{const browser=$('#pocketBrowser');browser.hidden=!browser.hidden;$('#pocketExpand').setAttribute('aria-expanded',!browser.hidden);$('#pocketExpand span').textContent=browser.hidden?'⌄':'⌃';requestAnimationFrame(constrainDock)};
$('#pocketDetails').ontoggle=()=>requestAnimationFrame(constrainDock);$('#pocketClear').onclick=()=>{pocketStop();pocketChord=null;pocketRefresh()};
async function pocketHear(step){pocketStop();if(!pocketChord)return;const generation=pocketAudioGeneration,notes=pocketMidi(),base=(octave+1)*12;await audio();if(generation!==pocketAudioGeneration||document.hidden||$('#pianoPanel').hidden&&!pianoFullscreenOpen)return;notes.forEach((m,i)=>{const id=`pocket-${generation}-${i}`,start=step*i;pocketAuditionTimers.push(setTimeout(()=>{if(generation===pocketAudioGeneration)noteOn(id,m-base)},start),setTimeout(()=>noteOff(id),start+700))})}
$('#pocketHear').onclick=()=>pocketHear(0);$('#pocketArpeggio').onclick=()=>pocketHear(260);
const pocketBaseKeys=pianoKeys;pianoKeys=function(){pocketBaseKeys();pocketPaint()};const pocketBaseOctave=changeOctave;changeOctave=function(delta){pocketStop();pocketBaseOctave(delta)};
const pocketBaseOpen=openPiano;openPiano=function(open){if(!open)pocketStop();pocketBaseOpen(open)};
const pocketBaseEnter=enterFullscreenPiano;enterFullscreenPiano=async function(){pocketStop();fullPiano.querySelector('.full-piano-stage').before(pocketLab);await pocketBaseEnter();pocketFit();pocketPaint()};fullscreenTrigger.onclick=enterFullscreenPiano;
const pocketBaseRestore=restorePiano;restorePiano=function(){pocketStop();pocketHome.after(pocketLab);pocketBaseRestore()};
window.addEventListener('blur',pocketStop);document.addEventListener('visibilitychange',()=>{if(document.hidden)pocketStop()});pocketRefresh();
